<?php
// Included by index.php after app.php has initialized the session.
if(!defined('SERVICES')){http_response_code(404);exit;}
$reviews=[];$reviewTotal=0;$reviewAverage=null;$reviewUnavailable=false;$myReview=null;
$ratingCounts=array_fill(1,5,0);
try{
 $reviewDb=db();$summary=$reviewDb->query('SELECT COUNT(*) AS total,AVG(rating) AS average FROM reviews')->fetch();
 $reviewTotal=(int)$summary['total'];$reviewAverage=$summary['average'];
 foreach($reviewDb->query('SELECT rating,COUNT(*) AS total FROM reviews GROUP BY rating') as $ratingRow)$ratingCounts[(int)$ratingRow['rating']]=(int)$ratingRow['total'];
 $reviews=$reviewDb->query('SELECT u.name,r.rating,r.comment,r.created_at FROM reviews r JOIN users u ON u.id=r.user_id ORDER BY r.created_at DESC,r.id DESC LIMIT 12')->fetchAll();
 if(!empty($_SESSION['user_id'])){$stmt=$reviewDb->prepare('SELECT rating,comment FROM reviews WHERE user_id=?');$stmt->execute([$_SESSION['user_id']]);$myReview=$stmt->fetch();}
}catch(Throwable $e){error_log($e->getMessage());$reviewUnavailable=true;}
$reviewDraft=$_SESSION['review_draft']??($myReview?:['rating'=>5,'comment'=>'']);
$reviewError=$_SESSION['review_error']??'';$reviewSuccess=$_SESSION['review_success']??'';
unset($_SESSION['review_draft'],$_SESSION['review_error'],$_SESSION['review_success']);
?>
<section id="reviews" class="section wrap reviews-section" aria-labelledby="reviews-title"><div class="section-heading"><div><p class="eyebrow">CUSTOMER REVIEWS</p><h2 id="reviews-title">Your experience.<br><span>Your words.</span></h2></div><div class="review-summary"><?php if($reviewTotal): ?><strong><?=h(number_format((float)$reviewAverage,1))?><span>/ 5</span></strong><p>From <?=$reviewTotal?> customer <?=$reviewTotal===1?'review':'reviews'?></p><?php else: ?><span class="review-summary-icon" aria-hidden="true">✧</span><p>Share your experience with The Auto Hub.</p><?php endif; ?></div></div>
<?php if(!$reviewUnavailable): ?><div class="public-review-overview"><div class="public-review-score"><span class="public-review-label">THE AUTO HUB EXPERIENCE</span><strong><?=$reviewTotal?h(number_format((float)$reviewAverage,1)):'—'?></strong><span class="public-review-score-caption"><?=$reviewTotal?'Average rating out of 5':'Your story starts the conversation'?></span><p><?=$reviewTotal?> customer <?=$reviewTotal===1?'review':'reviews'?> · Real feedback, in their own words.</p></div><div class="public-review-distribution" aria-label="Rating breakdown"><?php for($stars=5;$stars>=1;$stars--): ?><div class="review-rating-row"><span><?=$stars?> <span aria-hidden="true">★</span></span><meter min="0" max="<?=max(1,$reviewTotal)?>" value="<?=$ratingCounts[$stars]?>" aria-label="<?=$stars?> stars: <?=$ratingCounts[$stars]?> reviews"></meter><span><?=$ratingCounts[$stars]?></span></div><?php endfor; ?></div><a class="public-review-cta" href="#write-review"><span aria-hidden="true">✎</span><strong>Your voice matters.</strong><small>Share a little about your visit.</small><b><?=$myReview?'Update your review':'Write a review'?> ↗</b></a></div><?php endif; ?><div class="reviews-layout"><div class="review-feed"><?php if($reviewUnavailable): ?><div class="reviews-empty"><h3>Reviews are temporarily unavailable.</h3><p>Please check back shortly.</p></div><?php elseif(!$reviews): ?><div class="reviews-empty"><span aria-hidden="true">“</span><h3>Be the first to share your experience.</h3><p>Your honest feedback helps other customers discover the right vehicle care.</p></div><?php else: ?><div class="review-cards"><?php foreach($reviews as $review): ?><article class="review-card"><div class="review-card-top"><span class="review-avatar" aria-hidden="true"><?=h(function_exists('mb_substr')?mb_substr($review['name'],0,1):substr($review['name'],0,1))?></span><div><h3><?=h($review['name'])?></h3><time datetime="<?=h(date('Y-m-d',strtotime($review['created_at'])))?>"><?=h(date('d M Y',strtotime($review['created_at'])))?></time></div></div><div class="review-stars" aria-label="<?=h($review['rating'])?> out of 5 stars"><span aria-hidden="true"><?=str_repeat('★',(int)$review['rating'])?><span class="unfilled-stars"><?=str_repeat('★',5-(int)$review['rating'])?></span></span></div><p class="review-comment"><?=nl2br(h($review['comment']))?></p></article><?php endforeach; ?></div><?php if($reviewTotal>12): ?><p class="review-latest">Showing the latest 12 reviews.</p><?php endif; ?><?php endif; ?></div>
<aside class="write-review" id="write-review"><span class="write-review-icon" aria-hidden="true">✎</span><h3><?=$myReview?'Update your review':'Leave a review'?></h3><p>Tell us about your experience. Your account name, rating and comment will be public.</p><?php if($reviewError): ?><p class="review-error" role="alert"><?=h($reviewError)?></p><?php endif; ?><?php if($reviewSuccess): ?><p class="review-success" role="status"><?=h($reviewSuccess)?></p><?php endif; ?><?php if(empty($_SESSION['user_id'])): ?><a class="button" href="login.php">Sign in to write a review <span>↗</span></a><p class="review-small">New here? <a href="login.php?mode=register">Create an account</a></p><?php elseif(!$reviewUnavailable): ?><form method="post" action="submit-review.php"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><label for="review-rating">Your rating</label><select id="review-rating" name="rating" required><?php for($star=5;$star>=1;$star--): ?><option value="<?=$star?>" <?=(int)$reviewDraft['rating']===$star?'selected':''?>><?=$star?> / 5 — <?=['','Poor','Fair','Good','Very good','Excellent'][$star]?></option><?php endfor; ?></select><label for="review-comment">Your comment</label><textarea id="review-comment" name="comment" rows="5" minlength="10" maxlength="2000" placeholder="How was your experience with The Auto Hub?" required><?=h($reviewDraft['comment'])?></textarea><p class="review-small">10–2,000 characters. Please keep private contact details out of your comment. One review per account; you can update it here.</p><button class="button" type="submit"><?=$myReview?'Update review':'Publish review'?> <span>↗</span></button></form><?php endif; ?></aside></div></section>

